import sys
import json
import gzip
import hashlib
import base64

def is_valid_b64(s):
    if not isinstance(s, str):
        return False
    if len(s) == 0:
        return True
    if len(s) % 4 != 0:
        return False
    alpha = set('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/')
    for c in s:
        if c != '=' and c not in alpha:
            return False
    for i, c in enumerate(s):
        if c == '=' and i < len(s) - 1:
            return False
    n_eq = s.count('=')
    if n_eq > 2 or n_eq == 1:
        return False
    try:
        base64.b64decode(s, validate=True)
        return True
    except Exception:
        return False

def build_tar_header(path, content_size, mode):
    h = bytearray(512)
    # name
    pb = path.encode('utf-8')
    h[0:100] = pb + b'\x00' * (100 - len(pb))
    # mode: 8 bytes, 7 octal + NUL
    h[100:108] = f"{mode:07o}\x00".encode()
    # uid
    h[108:116] = b"0\x00\x00\x00\x00\x00\x00\x00"
    # gid
    h[116:124] = b"0\x00\x00\x00\x00\x00\x00\x00"
    # size: 12 bytes, 11 octal + NUL
    h[124:136] = f"{content_size:011o}\x00".encode()
    # mtime: 12 bytes
    h[136:148] = f"{0:011o}\x00".encode()
    # checksum: 8 bytes (spaces for now)
    h[148:156] = b' ' * 8
    # typeflag
    h[156] = ord('0')
    # linkname: NUL
    # magic: ustar\0 at 257
    h[257:263] = b'ustar\x00'
    # version: 2 bytes at 263
    h[263:265] = b'00'
    # uname/gname/devmajor/devminor/prefix: all NUL (already)
    # Compute checksum
    chk = sum(h)
    h[148:156] = f"{chk:06o}\x00".encode()
    return bytes(h)

def build_tar(members):
    data = bytearray()
    for path, content, mode in members:
        data.extend(build_tar_header(path, len(content), mode))
        data.extend(content)
        pad = (512 - (len(content) % 512)) % 512
        data.extend(b'\x00' * pad)
    data.extend(b'\x00' * 1024)
    return bytes(data)

def reject():
    print(json.dumps({"error": "invalid_request"}, separators=(',', ':')))
    sys.exit(0)

def main():
    try:
        raw = sys.stdin.buffer.read()
        req = json.loads(raw.decode('utf-8'))
    except Exception:
        reject()

    if not isinstance(req, dict):
        reject()
    if set(req.keys()) != {"members"}:
        reject()
    members = req["members"]
    if not isinstance(members, list):
        reject()
    if not (1 <= len(members) <= 64):
        reject()

    seen = set()
    valid = []
    total = 0

    for m in members:
        if not isinstance(m, dict):
            reject()
        if set(m.keys()) != {"path", "content_b64", "mode"}:
            reject()
        path = m["path"]
        cb64 = m["content_b64"]
        mode = m["mode"]

        if not isinstance(path, str) or path == '':
            reject()
        if path.startswith('/') or '\\' in path:
            reject()
        for ch in path:
            if ord(ch) < 0x20 or ord(ch) == 0x7F:
                reject()
        comps = path.split('/')
        if any(c in ('', '.', '..') for c in comps):
            reject()
        if len(path.encode('utf-8')) > 100:
            reject()
        if path in seen:
            reject()
        seen.add(path)

        if not is_valid_b64(cb64):
            reject()
        content = base64.b64decode(cb64)
        if len(content) > 65536:
            reject()
        total += len(content)
        if total > 131072:
            reject()

        if isinstance(mode, bool) or not isinstance(mode, int):
            reject()
        if not (0 <= mode <= 511):
            reject()

        valid.append((path, content, mode))

    valid.sort(key=lambda x: x[0])
    tar = build_tar(valid)
    compressed = gzip.compress(tar, mtime=0)
    result = {
        "format": "tar+gzip",
        "bundle_b64": base64.b64encode(compressed).decode('ascii'),
        "sha256": hashlib.sha256(compressed).hexdigest(),
    }
    print(json.dumps(result, separators=(',', ':')))

main()
